fn state_set_off(state: &Arc<RemoteGatewayState>) {
    let mut config = state.config.write();
    config.mode = RemoteNetworkMode::Off;
    *state.is_running.write() = false;
    *state.bound_address.write() = None;
    drop(config);
    persist_config_best_effort(state);
}

fn persist_config_best_effort(state: &RemoteGatewayState) {
    if let Err(error) = state.persist_config() {
        tracing::warn!("failed to persist remote gateway config: {error}");
    }
}

